@Test
public void testFilter() throws Exception {
    Document<Feed> doc = AtomUtils.parseDocument("file:src/test/data/feed.atom");
    assertNotNull(doc);
    // timestamp from the feed to use as base
    // 2007-11-13T13:35:25.014Z
    Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("GMT+1:00"));
    cal.set(2007, Calendar.NOVEMBER, 13, 14, 35, 0);
    EntryFilter filter = new UpdatedDateFilter(cal.getTime());
    List<Entry> entries = doc.getRoot().getEntries();
    // must reverse backwards
    for (int i = entries.size() - 1; i > 0; i--) {
        Entry entry = entries.get(i);
        boolean valid = filter.isValidEntry(null, doc, entry);
        // only the 3 last should be true
        if (i > 3) {
            assertEquals("not valid", false, valid);
        } else {
            assertEquals("valid", true, valid);
        }
    }
}

@Test
public void testStringToAddressConversion() throws Exception {
    DefaultCamelContext context = null;
    try {
        context = new DefaultCamelContext();
        context.start();
        TypeConverterRegistry registry = context.getTypeConverterRegistry();
        TypeConverter converter = registry.lookup(Address.class, String.class);
        Assert.assertNotNull(converter);
        Assert.assertEquals("127.0.0.1", converter.mandatoryConvertTo(Address.class, "127.0.0.1:1234").host());
        Assert.assertEquals(1234, converter.mandatoryConvertTo(Address.class, "127.0.0.1:1234").port());
    } finally {
        if (context != null) {
            context.stop();
        }
    }
}

