@Test
public void createEndpointWithMaximalConfiguration() throws Exception {
    AmazonSQSClientMock mock = new AmazonSQSClientMock();
    context.getRegistry().bind("amazonSQSClient", mock);
    SqsComponent component = new SqsComponent(context);
    SqsEndpoint endpoint = (SqsEndpoint) component.createEndpoint("aws-sqs://MyQueue?amazonSQSClient=#amazonSQSClient&accessKey=xxx" + "&secretKey=yyy&attributeNames=color,size" + "&messageAttributeNames=msgColor,msgSize&DefaultVisibilityTimeout=1000&visibilityTimeout=2000&maximumMessageSize=65536&messageRetentionPeriod=1209600&policy=" + "%7B%22Version%22%3A%222008-10-17%22%2C%22Id%22%3A%22%2F195004372649%2FMyQueue%2FSQSDefaultPolicy%22%2C%22Statement%22%3A%5B%7B%22Sid%22%3A%22Queue1ReceiveMessage%22%2C%22" + "Effect%22%3A%22Allow%22%2C%22Principal%22%3A%7B%22AWS%22%3A%22*%22%7D%2C%22Action%22%3A%22SQS%3AReceiveMessage%22%2C%22Resource%22%3A%22%2F195004372649%2FMyQueue%22%7D%5D%7D" + "&delaySeconds=123&receiveMessageWaitTimeSeconds=10&waitTimeSeconds=20" + "&queueOwnerAWSAccountId=111222333&region=us-east-1" + "&redrivePolicy={\"maxReceiveCount\":\"5\", \"deadLetterTargetArn\":\"arn:aws:sqs:us-east-1:195004372649:MyDeadLetterQueue\"}");
    assertEquals("MyQueue", endpoint.getConfiguration().getQueueName());
    assertEquals("xxx", endpoint.getConfiguration().getAccessKey());
    assertEquals("yyy", endpoint.getConfiguration().getSecretKey());
    assertNotNull(endpoint.getConfiguration().getAmazonSQSClient());
    assertEquals("color,size", endpoint.getConfiguration().getAttributeNames());
    assertEquals("msgColor,msgSize", endpoint.getConfiguration().getMessageAttributeNames());
    assertEquals(new Integer(1000), endpoint.getConfiguration().getDefaultVisibilityTimeout());
    assertEquals(new Integer(2000), endpoint.getConfiguration().getVisibilityTimeout());
    assertEquals(new Integer(65536), endpoint.getConfiguration().getMaximumMessageSize());
    assertEquals(new Integer(1209600), endpoint.getConfiguration().getMessageRetentionPeriod());
    assertEquals("{\"Version\":\"2008-10-17\",\"Id\":\"/195004372649/MyQueue/SQSDefaultPolicy\",\"Statement\":[{\"Sid\":\"Queue1ReceiveMessage\",\"Effect\":\"Allow\",\"Principal\":" + "{\"AWS\":\"*\"},\"Action\":\"SQS:ReceiveMessage\",\"Resource\":\"/195004372649/MyQueue\"}]}", endpoint.getConfiguration().getPolicy());
    assertEquals("{\"maxReceiveCount\":\"5\", \"deadLetterTargetArn\":\"arn:aws:sqs:us-east-1:195004372649:MyDeadLetterQueue\"}", endpoint.getConfiguration().getRedrivePolicy());
    assertEquals(new Integer(123), endpoint.getConfiguration().getDelaySeconds());
    assertEquals(Integer.valueOf(10), endpoint.getConfiguration().getReceiveMessageWaitTimeSeconds());
    assertEquals(Integer.valueOf(20), endpoint.getConfiguration().getWaitTimeSeconds());
    assertEquals("111222333", endpoint.getConfiguration().getQueueOwnerAWSAccountId());
    assertEquals("us-east-1", endpoint.getConfiguration().getRegion());
}

