public void testBeanstalkException() throws Exception {
    if (!canTest()) {
        return;
    }
    final Job jobMock = mock(Job.class);
    final long jobId = 111;
    final byte[] payload = Helper.stringToBytes(testMessage);
    when(jobMock.getJobId()).thenReturn(jobId);
