@Test
public void testServiceDiscovery() throws Exception {
    ConsulConfiguration configuration = new ConsulConfiguration();
    configuration.setUrl(consulUrl());
    ServiceDiscovery discovery = new ConsulServiceDiscovery(configuration);
    List<ServiceDefinition> services = discovery.getServices("my-service");
    assertNotNull(services);
    assertEquals(6, services.size());
    for (ServiceDefinition service : services) {
        Assertions.assertThat(service.getMetadata()).isNotEmpty();
        Assertions.assertThat(service.getMetadata()).containsEntry(ServiceDefinition.SERVICE_META_NAME, "my-service");
        Assertions.assertThat(service.getMetadata()).containsKey(ServiceDefinition.SERVICE_META_ID);
        Assertions.assertThat(service.getMetadata()).containsKey("a-tag");
        Assertions.assertThat(service.getMetadata()).containsEntry("key1", "value1");
        Assertions.assertThat(service.getMetadata()).containsEntry("key2", "value2");
        Assertions.assertThat(service.getMetadata()).containsEntry("meta-key", "meta-val");
        Assertions.assertThat("" + service.getHealth().isHealthy()).isEqualTo(service.getMetadata().get("healthy"));
    }
}

@Test
public void testRegistrationFromRoute() throws Exception {
    final CatalogClient catalog = getConsul().catalogClient();
    final HealthClient health = getConsul().healthClient();
    // the service should not be registered as the route is not running
    assertTrue(catalog.getService(SERVICE_NAME).getResponse().isEmpty());
    // let start the route
    context().getRouteController().startRoute(SERVICE_ID);
    // check that service has been registered
    List<CatalogService> services = catalog.getService(SERVICE_NAME).getResponse();
    assertEquals(1, services.size());
    assertEquals(SERVICE_PORT, services.get(0).getServicePort());
    assertEquals("localhost", services.get(0).getServiceAddress());
    assertTrue(services.get(0).getServiceTags().contains(ServiceDefinition.SERVICE_META_PROTOCOL + "=http"));
    assertTrue(services.get(0).getServiceTags().contains(ServiceDefinition.SERVICE_META_PATH + "=/service/endpoint"));
    getMetadata().forEach((k, v) -> {
        assertTrue(services.get(0).getServiceTags().contains(k + "=" + v));
    });
    List<ServiceHealth> checks = health.getHealthyServiceInstances(SERVICE_NAME).getResponse();
    assertEquals(1, checks.size());
    assertEquals(SERVICE_PORT, checks.get(0).getService().getPort());
    assertEquals("localhost", checks.get(0).getService().getAddress());
    // let stop the route
    context().getRouteController().stopRoute(SERVICE_ID);
    // the service should be removed once the route is stopped
    assertTrue(catalog.getService(SERVICE_NAME).getResponse().isEmpty());
}

@Test
public void testSimpleServiceRegistration() throws Exception {
    ConsulServiceRegistry registry = new ConsulServiceRegistry();
    registry.setCamelContext(context());
    registry.setUrl(consulUrl());
    registry.setServiceHost("service-host");
    registry.setOverrideServiceHost(true);
    registry.start();
    registry.register(DefaultServiceDefinition.builder().withId("my-id").withName("service-name").withHost("my-host").withPort(9091).build());
    final CatalogClient catalog = getConsul().catalogClient();
    final HealthClient health = getConsul().healthClient();
    // check that service has been registered
    List<CatalogService> services = catalog.getService("service-name").getResponse();
    assertEquals(1, services.size());
    assertEquals(9091, services.get(0).getServicePort());
    assertEquals("service-host", services.get(0).getServiceAddress());
    assertEquals("my-id", services.get(0).getServiceId());
    List<ServiceHealth> checks = health.getHealthyServiceInstances("service-name").getResponse();
    assertEquals(1, checks.size());
    assertEquals(9091, checks.get(0).getService().getPort());
    assertEquals("service-host", checks.get(0).getService().getAddress());
    assertEquals("my-id", checks.get(0).getService().getId());
    registry.stop();
    // check that service has been de registered on service registry shutdown
    assertEquals(0, catalog.getService("service-name").getResponse().size());
    assertEquals(0, health.getServiceChecks("service-name").getResponse().size());
}

