@Test
public void testInvokeGreetMeOverProvider() throws Exception {
    Service service = Service.create(serviceName);
    service.addPort(routerPortName, "http://schemas.xmlsoap.org/soap/", "http://localhost:" + getPort2() + "/" + getClass().getSimpleName() + "/CamelContext/RouterPort");
    Greeter greeter = service.getPort(routerPortName, Greeter.class);
    org.apache.cxf.endpoint.Client client = org.apache.cxf.frontend.ClientProxy.getClient(greeter);
    VerifyInboundInterceptor icp = new VerifyInboundInterceptor();
    client.getInInterceptors().add(icp);
    int ic = implementor.getInvocationCount();
    icp.setCalled(false);
    String reply = greeter.greetMe("test");
    assertEquals("Got the wrong reply ", "Hello test", reply);
    assertTrue("No Inbound message received", icp.isCalled());
    assertEquals("The target service not invoked", ++ic, implementor.getInvocationCount());
    icp.setCalled(false);
    greeter.greetMeOneWay("call greetMe OneWay !");
    assertFalse("An unnecessary inbound message", icp.isCalled());
    // wait a few seconds for the async oneway service to be invoked
    Thread.sleep(3000);
    assertEquals("The target service not invoked", ++ic, implementor.getInvocationCount());
}

@Test
public void testInvokeRouter() throws IOException {
    CloseableHttpClient httpclient = HttpClients.createDefault();
    long contentLength = 0;
    boolean isChunked = false;
    String receivedContent = null;
    try {
        HttpPost httppost = new HttpPost("http://localhost:" + CXFTestSupport.getPort1() + "/TEST/PROXY");
        StringEntity reqEntity = new StringEntity(REQUEST_MESSAGE, ContentType.TEXT_XML);
        reqEntity.setChunked(false);
        httppost.setEntity(reqEntity);
        CloseableHttpResponse response = httpclient.execute(httppost);
        try {
            HttpEntity respEntity = response.getEntity();
            contentLength = respEntity.getContentLength();
            isChunked = respEntity.isChunked();
            receivedContent = EntityUtils.toString(respEntity);
            EntityUtils.consume(response.getEntity());
        } finally {
            response.close();
        }
    } finally {
        httpclient.close();
    }
    assertNotNull(receivedContent);
    // chunked encoding is fine, we don't need to check the content length
    if (!isChunked) {
        assertEquals(receivedContent.length(), contentLength);
    }
    assertTrue("[" + receivedContent + "] does not contain [" + RESPONSE_STRING + "]", receivedContent.contains(RESPONSE_STRING));
    // check whether the response was cut off by the client because the
    // Content-Length was wrong
    assertTrue("[" + receivedContent + "] does not contain the closing Envelope tag.", receivedContent.matches(".*\\</.*:Envelope\\>"));
}

