        @Override
        public void configure() throws Exception {
            weaveByToString(".*java.*").replace().to("exec:java?commandExecutor=#executorMock");
        }
    });
    context.start();
    output.setExpectedMessageCount(0);
    Exchange out = sendFailExchange(EXIT_WITH_VALUE_0, NO_TIMEOUT);
