    assertEquals("myfile.txt", FtpUtils.extractDirNameFromAbsolutePath(path));
    path = "/test/depth1/myfile.txt/";
    assertEquals("myfile.txt", FtpUtils.extractDirNameFromAbsolutePath(path));
    path = "test/depth1/";
    assertEquals("depth1", FtpUtils.extractDirNameFromAbsolutePath(path));
    path = "test/depth1";
    assertEquals("depth1", FtpUtils.extractDirNameFromAbsolutePath(path));
    path = "depth1";
    assertEquals("depth1", FtpUtils.extractDirNameFromAbsolutePath(path));
    path = "\\test\\depth1\\myfile.txt";
    assertEquals("myfile.txt", FtpUtils.extractDirNameFromAbsolutePath(path));
    path = "\\test\\depth1\\myfile.txt\\";
    assertEquals("myfile.txt", FtpUtils.extractDirNameFromAbsolutePath(path));
    path = "test\\depth1\\";
    assertEquals("depth1", FtpUtils.extractDirNameFromAbsolutePath(path));
    path = "test\\depth1";
    assertEquals("depth1", FtpUtils.extractDirNameFromAbsolutePath(path));
}

