public void testRemoteFileEndpointFiles() {
    assertRemoteFileEndpointFile("ftp://hostname/foo/bar", "foo/bar");
    assertRemoteFileEndpointFile("ftp://hostname/foo/bar/", "foo/bar/");
    assertRemoteFileEndpointFile("ftp://hostname/foo/", "foo/");
    assertRemoteFileEndpointFile("ftp://hostname/foo", "foo");
    assertRemoteFileEndpointFile("ftp://hostname/", "");
    assertRemoteFileEndpointFile("ftp://hostname", "");
    assertRemoteFileEndpointFile("ftp://hostname//", "");
    assertRemoteFileEndpointFile("ftp://hostname//foo/bar", "foo/bar");
