@Test
public void testSimulateInOnlyUsingWireTap() throws Exception {
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() throws Exception {
            // START SNIPPET: e1
            from("jetty://http://localhost:{{port}}/myserver").// turn the route to in only as we do not want jetty to wait for the response
            // we can do this using the wiretap EIP pattern
            wireTap("direct:continue").// and then construct a canned empty response
            transform(constant("OK"));
            from("direct:continue").delay(1500).process(new Processor() {

                public void process(Exchange exchange) throws Exception {
                    route += "B";
                }
            }).to("mock:result");
            // END SNIPPET: e1
        }
    });
    context.start();
    route = "";
    MockEndpoint mock = getMockEndpoint("mock:result");
    mock.expectedMessageCount(1);
    mock.expectedHeaderReceived("foo", "bar");
    String reply = template.requestBody("http://localhost:{{port}}/myserver?foo=bar", null, String.class);
    route += "A";
    assertEquals("OK", reply);
    assertMockEndpointsSatisfied();
    assertEquals("AB", route);
}

