    Thread.sleep(IDLE_TIMEOUT / 2);
    source.sendBody(Hl7TestMessageGenerator.generateMessage());
    assertTrue("Should have completed two exchanges", done.matches(5, TimeUnit.SECONDS));
    Thread.sleep((long) (IDLE_TIMEOUT * 1.1));
    try {
