@Test
public void testBulkWrite() throws Exception {
    // Test that the collection has 0 documents in it
    assertEquals(0, testCollection.count());
    pumpDataIntoTestCollection();
    List<WriteModel<Document>> bulkOperations = Arrays.asList(new InsertOneModel<>(new Document("scientist", "Pierre Curie")), new UpdateOneModel<>(new Document("_id", "2"), new Document("$set", new Document("scientist", "Charles Darwin"))), new UpdateManyModel<>(new Document("scientist", "Curie"), new Document("$set", new Document("scientist", "Marie Curie"))), new ReplaceOneModel<>(new Document("_id", "1"), new Document("scientist", "Albert Einstein")), new DeleteOneModel<>(new Document("_id", "3")), new DeleteManyModel<>(new Document("scientist", "Bohr")));
    BulkWriteResult result = template.requestBody("direct:bulkWrite", bulkOperations, BulkWriteResult.class);
    assertNotNull(result);
    // 1 insert
    assertEquals("Records inserted should be 2 : ", 1, result.getInsertedCount());
    // 1 updateOne + 100 updateMany + 1 replaceOne
    assertEquals("Records matched should be 102 : ", 102, result.getMatchedCount());
    assertEquals("Records modified should be 102 : ", 102, result.getModifiedCount());
    // 1 deleteOne + 100 deleteMany
    assertEquals("Records deleted should be 101 : ", 101, result.getDeletedCount());
}

