    crs.process("direct:stream", Integer.class, publisher -> Flowable.fromPublisher(publisher).map(Math::negateExact));
    for (int i = 1; i <= 3; i++) {
        Assert.assertEquals("after stream: " + (-i), template.requestBody("direct:source", i, String.class));
    }
}

