            from("sjms:queue:test").to("mock:test");
        }
    };
    context.addRoutes(routeBuilder);
    context.start();
    getMockEndpoint("mock:test").expectedMessageCount(1);
    template.sendBody("sjms:queue:test", "Hello World");
