 * multiple routes that we are thread safe and behave accordingly.
 *
 * @throws Exception
 */
@Test
public void testRoute() throws Exception {
    final String destinationName = "sjms:queue:one.consumer.one.route.test";
    int routeCount = 2;
    int consumerCount = 1;
    int batchCount = 1;
    int messageCount = 20;
    int maxAttemptsCount = 10;
    int totalRedeliverdFalse = 10;
    int totalRedeliveredTrue = 1;
    runTest(destinationName, routeCount, messageCount, totalRedeliverdFalse, totalRedeliveredTrue, batchCount, consumerCount, maxAttemptsCount);
}

@Test(expected = FailedToStartRouteException.class)
public void test() throws Exception {
    CamelContext context = new DefaultCamelContext();
    context.addRoutes(createRouteBuilder());
    SjmsComponent component = context.getComponent("sjms", SjmsComponent.class);
    component.setConnectionFactory(CamelJmsTestHelper.createConnectionFactory());
    try {
        context.start();
    } catch (Throwable t) {
        Assert.assertEquals(FailedToStartRouteException.class, t.getClass());
        Assert.assertEquals(FailedToCreateProducerException.class, t.getCause().getClass());
        Assert.assertEquals(IllegalArgumentException.class, t.getCause().getCause().getClass());
        LOG.info("Exception was thrown as expected", t);
        throw t;
    }
}

