@Test
public void testConsumeTemplate() throws Exception {
    // we expect Hello World received in our mock endpoint
    mock.expectedBodiesReceived("Hello World");
    // we use the producer template to send a message to the seda:start endpoint
    producer.sendBody("seda:start", "Hello World");
    // we consume the body from seda:start
    String body = consumer.receiveBody("seda:start", String.class);
    assertEquals("Hello World", body);
    // and then we send the body again to seda:foo so it will be routed to the mock
    // endpoint so our unit test can complete
    producer.sendBody("seda:foo", body);
    // assert mock received the body
    mock.assertIsSatisfied();
}

@Test
public void testEndpointProperty() throws Exception {
    getMockEndpoint("mock:result").expectedMessageCount(2);
    template.sendBody("ref:foo", "Hello World");
    template.sendBody("ref:bar", "Bye World");
    assertMockEndpointsSatisfied();
    SedaEndpoint foo = applicationContext.getBean("foo", SedaEndpoint.class);
    assertNotNull(foo);
    assertEquals(100, foo.getSize());
    assertEquals(250, foo.getPollTimeout());
    assertEquals(true, foo.isBlockWhenFull());
    assertEquals("seda://foo?blockWhenFull=true&pollTimeout=250&size=100", foo.getEndpointUri());
    SedaEndpoint bar = applicationContext.getBean("bar", SedaEndpoint.class);
    assertNotNull(bar);
    assertEquals(200, bar.getSize());
    assertEquals("seda://bar?size=200", bar.getEndpointUri());
}

