@Test
public void testRouteRestart() throws Exception {
    Assert.assertNotNull(context.getRouteController());
    Assert.assertTrue(context.getRouteController() instanceof SupervisingRouteController);
    SupervisingRouteController controller = context.getRouteController().unwrap(SupervisingRouteController.class);
    // Wait for the controller to start the routes
    await().atMost(3, TimeUnit.SECONDS).untilAsserted(() -> {
        // now its suspended by the policy
        Assert.assertEquals(ServiceStatus.Started, context.getRouteController().getRouteStatus("foo"));
        Assert.assertEquals(ServiceStatus.Started, context.getRouteController().getRouteStatus("bar"));
        Assert.assertEquals(ServiceStatus.Started, context.getRouteController().getRouteStatus("dummy"));
    });
    // restart the dummy route which should fail on first attempt
    controller.stopRoute("dummy");
    Assert.assertNull(context.getRoute("dummy").getRouteContext().getRouteController());
    try {
        controller.startRoute("dummy");
    } catch (Exception e) {
        Assert.assertEquals("Forced error on restart", e.getCause().getMessage());
    }
    Assert.assertTrue(controller.getBackOffContext("dummy").isPresent());
    Assert.assertEquals(BackOffTimer.Task.Status.Active, controller.getBackOffContext("dummy").get().getStatus());
    Assert.assertTrue(controller.getBackOffContext("dummy").get().getCurrentAttempts() > 0);
    // Wait for wile to give time to the controller to start the route
    await().atMost(2, TimeUnit.SECONDS).untilAsserted(() -> {
        // now its suspended by the policy
        Assert.assertEquals(ServiceStatus.Started, context.getRouteController().getRouteStatus("dummy"));
        Assert.assertNotNull(context.getRoute("dummy").getRouteContext().getRouteController());
        Assert.assertFalse(controller.getBackOffContext("dummy").isPresent());
    });
}

@Test
public void test() throws Exception {
    Assert.assertNotNull(context.getRouteController());
    Assert.assertTrue(context.getRouteController() instanceof SupervisingRouteController);
    SupervisingRouteController controller = context.getRouteController().unwrap(SupervisingRouteController.class);
    Assert.assertEquals(3, controller.getControlledRoutes().size());
    Assert.assertEquals(2, controller.getInitialDelay().getSeconds());
    // Route foo
    BackOff foo = controller.getBackOff("foo");
    Assert.assertEquals(1, foo.getDelay().getSeconds());
    Assert.assertEquals(Long.MAX_VALUE, foo.getMaxDelay().toMillis());
    Assert.assertEquals(10L, foo.getMaxAttempts().longValue());
    // Route bar
    BackOff bar = controller.getBackOff("bar");
    Assert.assertEquals(10, bar.getDelay().getSeconds());
    Assert.assertEquals(Long.MAX_VALUE, bar.getMaxDelay().toMillis());
    Assert.assertEquals(3L, bar.getMaxAttempts().longValue());
    Assert.assertEquals(controller, context.getRoute("foo").getRouteContext().getRouteController());
    Assert.assertEquals(controller, context.getRoute("bar").getRouteContext().getRouteController());
    Assert.assertNull(context.getRoute("timer-unmanaged").getRouteContext().getRouteController());
    Assert.assertNull(context.getRoute("timer-no-autostartup").getRouteContext().getRouteController());
    Assert.assertEquals(ServiceStatus.Stopped, context.getRouteController().getRouteStatus("foo"));
    Assert.assertEquals(ServiceStatus.Stopped, context.getRouteController().getRouteStatus("bar"));
}

