    wsclient1.reset(1);
    wsclient2.reset(1);
    wsclient3.reset(1);
    final String broadcastMsg = BROADCAST_MESSAGE_PREFIX + connectionKey2 + " " + connectionKey3;
    // this one should go to wsclient2 and wsclient3
    wsclient1.sendTextMessage(broadcastMsg);
    // this one should go to wsclient1 only
    wsclient1.sendTextMessage("private");
    wsclient2.await(10);
    Assert.assertEquals(broadcastMsg, wsclient2.getReceived(String.class).get(0));
    wsclient3.await(10);
    Assert.assertEquals(broadcastMsg, wsclient3.getReceived(String.class).get(0));
    wsclient1.await(10);
    Assert.assertEquals("private", wsclient1.getReceived(String.class).get(0));
    wsclient1.close();
    wsclient2.close();
    wsclient3.close();
}

