@Test
public void testContext() throws Exception {
    context().addRoutes(new RouteBuilder() {

        @Override
        public void configure() throws Exception {
            restConfiguration().host("0.0.0.0").port(port);
            from("webhook:wb-delegate://xx").transform(body().prepend("msg: "));
            from("webhook:wb-delegate://xx?webhookPath=/p2&webhookAutoRegister=false").transform(body().prepend("uri: "));
        }
    });
    assertEquals(0, registered.get());
    assertEquals(0, unregistered.get());
    context.start();
    Awaitility.waitAtMost(5, TimeUnit.SECONDS).until(() -> registered.get() == 1);
    assertEquals(0, unregistered.get());
    context.stop();
    Awaitility.waitAtMost(5, TimeUnit.SECONDS).until(() -> unregistered.get() == 1);
    assertEquals(1, registered.get());
}

