        }
    });
    try {
        template.sendBody("direct:a", "Hello World");
        fail("Should have thrown an exception");
    } catch (Exception e) {
        assertIsInstanceOf(IllegalArgumentException.class, e.getCause());
        assertEquals("Forced", e.getCause().getMessage());
    }
}

