@Test
public void testPropertiesComponentCacheClearedOnStop() throws Exception {
    context.start();
    context.resolvePropertyPlaceholders("{{cool.end}}");
    context.resolvePropertyPlaceholders("{{cool.end}}");
    context.resolvePropertyPlaceholders("{{cool.end}}");
    // one cache miss
    assertEquals(1, resolvedCount);
    context.stop();
    context.start();
    context.resolvePropertyPlaceholders("{{cool.end}}");
    context.resolvePropertyPlaceholders("{{cool.end}}");
    context.resolvePropertyPlaceholders("{{cool.end}}");
    // one more cache miss -- stop() cleared the cache
    assertEquals(2, resolvedCount);
}

