        // The stream is closed, so the temp file is gone.
        fail("we expect the exception here");
    } catch (Exception exception) {
        // do nothing
    }
    files = file.list();
    assertEquals("we should have no temp file", 0, files.length);
    IOHelper.close(cos);
}

