    // now lets check it works
    // send from C over B to results
    results.reset();
    results = getMockEndpoint("mock:results");
    results.expectedBodiesReceived(expectedBody);
    template.sendBody(endpointC, expectedBody);
    assertMockEndpointsSatisfied();
}

