    List<String> fileEntries = fileContent.collect(Collectors.toList());
    fileContent.close();
    //expected order
    Assert.assertThat(fileEntries, IsIterableContainingInOrder.contains("ZZZZZZZZZZ", "XXXXXXXXXX"));
