@Test
public void testNotSkiDuplicateWithFilter() throws Exception {
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() throws Exception {
            IdempotentRepository repo = MemoryIdempotentRepository.memoryIdempotentRepository(200);
            // START SNIPPET: e1
            from("direct:start").// instruct idempotent consumer to not skip duplicates as we will filter then our self
            idempotentConsumer(header("messageId")).messageIdRepository(repo).skipDuplicate(false).filter(exchangeProperty(Exchange.DUPLICATE_MESSAGE).isEqualTo(true)).// filter out duplicate messages by sending them to someplace else and then stop
            to("mock:duplicate").stop().end().// and here we process only new messages (no duplicates)
            to("mock:result");
            // END SNIPPET: e1
        }
    });
    context.start();
