@Test
public /*
     * The formatted exchange without limitation is 
     * Exchange[ExchangePattern: InOnly, BodyType: String, Body: This is the message body]
     * The "Exchange[", the "...", and the "]" do not count here, but the 
     * leading ", " that is removed later does count...
     */
void testFormatWithMaxCharsParameter() {
    exchangeFormatter.setMaxChars(60);
    String formattedExchange = exchangeFormatter.format(exchange);
    assertEquals(60 + "Exchange[...]".length() - ", ".length(), formattedExchange.length());
}

@Test
public /*
     * This limitation is really the length of the printed message body, not the
     * one of the message
     */
void testFormatWithBodyMaxChars() {
    camelContext.getGlobalOptions().put(Exchange.LOG_DEBUG_BODY_MAX_CHARS, "7");
    String formattedExchange = exchangeFormatter.format(exchange);
    assertFalse(formattedExchange.contains("This is "));
    assertTrue(formattedExchange.contains("This is"));
    camelContext.getGlobalOptions().remove(Exchange.LOG_DEBUG_BODY_MAX_CHARS);
}

@Test
public /*
     * These two limitations will first truncate the message body and then the
     * total message.
     */
void testFormatWithBoth() {
    camelContext.getGlobalOptions().put(Exchange.LOG_DEBUG_BODY_MAX_CHARS, "7");
    exchangeFormatter.setMaxChars(60);
    String formattedExchange = exchangeFormatter.format(exchange);
    assertEquals(60 + "Exchange[...]".length() - ", ".length(), formattedExchange.length());
    assertFalse(formattedExchange.contains("This is "));
    camelContext.getGlobalOptions().remove(Exchange.LOG_DEBUG_BODY_MAX_CHARS);
}

@Test
public void testDefaultOption() throws Exception {
    DefaultMaskingFormatter formatter = new DefaultMaskingFormatter();
    String answer = formatter.format("key=value, myPassword=foo,\n myPassphrase=\"foo bar\", secretKey='!@#$%^&*() -+[]{};:'");
    Assert.assertEquals("key=value, myPassword=\"xxxxx\",\n myPassphrase=\"xxxxx\", secretKey=\"xxxxx\"", answer);
    answer = formatter.format("<xmlPassword>\n foo bar \n</xmlPassword>\n<user password=\"asdf qwert\"/>");
    Assert.assertEquals("<xmlPassword>\n xxxxx \n</xmlPassword>\n<user password=\"xxxxx\"/>", answer);
    answer = formatter.format("{\"key\" : \"value\", \"My Password\":\"foo\", \"My SecretPassphrase\" : \"foo bar\", \"My SecretKey2\" : \"!@#$%^&*() -+[]{};:'\"}");
    Assert.assertEquals("{\"key\" : \"value\", \"My Password\":\"xxxxx\", \"My SecretPassphrase\" : \"xxxxx\", \"My SecretKey2\" : \"xxxxx\"}", answer);
}

