@Test
public void test() {
    AntPathMatcher matcher = new AntPathMatcher();
    assertTrue(matcher.match("*.txt", "blah.txt"));
    assertFalse(matcher.match("*.txt", "foo/blah.txt"));
    assertTrue(matcher.match("???.txt", "abc.txt"));
    assertTrue(matcher.match("abc.t?t", "abc.tnt"));
    assertFalse(matcher.match("???.txt", "abcd.txt"));
    assertTrue(matcher.match("**/*.txt", "blah.txt"));
    assertTrue(matcher.match("**/*.txt", "foo/blah.txt"));
    assertTrue(matcher.match("**/*.txt", "foo/bar/blah.txt"));
    assertTrue(matcher.match("foo/**/*.txt", "foo/bar/blah.txt"));
    assertTrue(matcher.match("foo/**/*.??", "foo/bar/blah.gz"));
    assertTrue(matcher.match("foo/**/*.txt", "foo/blah.txt"));
    assertFalse(matcher.match("foo/**/*.txt", "blah/blah.txt"));
}

@Test
public void testCaseSensitive() {
    AntPathMatcher matcher = new AntPathMatcher();
    assertTrue(matcher.match("foo/**/*.txt", "foo/blah.txt", true));
    assertTrue(matcher.match("foo/**/*.txt", "foo/blah.txt", false));
    assertTrue(matcher.match("foo/**/*.txt", "foo/BLAH.txt"));
    assertFalse(matcher.match("FOO/**/*.txt", "foo/blah.txt"));
    assertFalse(matcher.match("foo/**/*.TXT", "foo/blah.txt"));
    assertTrue(matcher.match("foo/**/*.TXT", "foo/blah.txt", false));
    assertTrue(matcher.match("FOO/**/*.txt", "foo/blah.txt", false));
    assertFalse(matcher.match("FOO/**/*.txt", "foo/blah.txt", true));
    assertFalse(matcher.match("FOO/**/*.txt", "foo/blah.txt", true));
}

@Test
public void testSimpleBackOff() {
    final BackOff backOff = BackOff.builder().build();
    final BackOffTimerTask context = new BackOffTimerTask(backOff, null, t -> true);
    long delay;
    for (int i = 1; i <= 5; i++) {
        delay = context.next();
        Assert.assertEquals(i, context.getCurrentAttempts());
        Assert.assertEquals(BackOff.DEFAULT_DELAY.toMillis(), delay);
        Assert.assertEquals(BackOff.DEFAULT_DELAY.toMillis(), context.getCurrentDelay());
        Assert.assertEquals(BackOff.DEFAULT_DELAY.toMillis() * i, context.getCurrentElapsedTime());
    }
}

@Test
public void testBackOffWithMultiplier() {
    final BackOff backOff = BackOff.builder().multiplier(1.5).build();
    final BackOffTimerTask context = new BackOffTimerTask(backOff, null, t -> true);
    long delay = BackOff.DEFAULT_DELAY.toMillis();
    long oldDelay;
    long elapsed = 0;
    for (int i = 1; i <= 5; i++) {
        oldDelay = delay;
        delay = context.next();
        elapsed += delay;
        Assert.assertEquals(i, context.getCurrentAttempts());
        Assert.assertEquals((long) (oldDelay * 1.5), delay);
        Assert.assertEquals((long) (oldDelay * 1.5), context.getCurrentDelay());
        Assert.assertEquals(elapsed, context.getCurrentElapsedTime(), 0);
    }
}

@Test
public void testBackOffWithMaxAttempts() {
    final BackOff backOff = BackOff.builder().maxAttempts(5L).build();
