@Test
public void testIsRaw() {
    List<Pair<Integer>> pairs = Arrays.asList(new Pair(3, 5), new Pair(8, 10));
    for (int i = 0; i < 3; i++) {
        assertFalse(URISupport.isRaw(i, pairs));
    }
    for (int i = 3; i < 6; i++) {
        assertTrue(URISupport.isRaw(i, pairs));
    }
    for (int i = 6; i < 8; i++) {
        assertFalse(URISupport.isRaw(i, pairs));
    }
    for (int i = 8; i < 11; i++) {
        assertTrue(URISupport.isRaw(i, pairs));
    }
    for (int i = 11; i < 15; i++) {
        assertFalse(URISupport.isRaw(i, pairs));
    }
}

