public void testServiceWithValidateUser() throws Exception {
    String response = sendMessageWithUsernameToken("jim", "jimspassword", "CXF");
    assertEquals(" Hello CXF", response);
    try {
        sendMessageWithUsernameToken("jim", "foo", "CXF");
