public void testComparator() {
    String label1 = "common";
    String label2 = "advanced";
    String label3 = "common";
    String label4 = "filter";
    String group1 = EndpointHelper.labelAsGroupName(label1, false, false);
    String group2 = EndpointHelper.labelAsGroupName(label2, false, false);
    String group3 = EndpointHelper.labelAsGroupName(label3, false, false);
    String group4 = EndpointHelper.labelAsGroupName(label4, false, false);
    EndpointOption op1 = new EndpointOption("first", "First", "string", true, "", "", "blah", null, null, false, false, null, false, group1, label1, false, null);
    EndpointOption op2 = new EndpointOption("synchronous", "Synchronous", "string", true, "", "", "blah", null, null, false, false, null, false, group2, label2, false, null);
    EndpointOption op3 = new EndpointOption("second", "Second", "string", true, "", "", "blah", null, null, false, false, null, false, group3, label3, false, null);
    EndpointOption op4 = new EndpointOption("country", "Country", "string", true, "", "", "blah", null, null, false, false, null, false, group4, label4, false, null);
    List<EndpointOption> list = new ArrayList<>();
    list.add(op1);
    list.add(op2);
    list.add(op3);
    list.add(op4);
    // then by label into the groups
    Collections.sort(list, EndpointHelper.createGroupAndLabelComparator());
    // common
    assertEquals("first", list.get(0).getName());
    // common
    assertEquals("second", list.get(1).getName());
    // advanced
    assertEquals("synchronous", list.get(2).getName());
    // filter
    assertEquals("country", list.get(3).getName());
}

